import 'package:flutter_test/flutter_test.dart';import 'package:toman_rates/features/forced_update/domain/version_models.dart';import 'package:toman_rates/core/utils/semver.dart';
void main(){test('forces only below minimum',(){final c=VersionConfig.fromJson({'current_version':'1.10.0','minimum_supported_version':'1.9.0','download_url':'https://example.com/app','telegram_url':'','release_notes':''});expect(SemanticVersion.parse('1.8.9').compareTo(c.minimum)<0,isTrue);expect(SemanticVersion.parse('1.9.0').compareTo(c.minimum)<0,isFalse);});test('rejects unsafe URL',(){expect(()=>VersionConfig.fromJson({'current_version':'1.0.0','minimum_supported_version':'1.0.0','download_url':'http://bad.test','telegram_url':'','release_notes':''}),throwsFormatException);});}
